static int diffOne(const char *a, const char *b) {
  int diff = 0;
  for (int i = 0; a[i]; i++) {
    if (a[i] != b[i]) diff++;
  }
  return diff;
}

char **findLadders(char *beginWord, char *endWord, char **wordList, int wordListSize, int *returnSize) {
  char **words = (char **)malloc(sizeof(char *) * (wordListSize + 1));
  int n = 0;
  words[n++] = beginWord;
  for (int i = 0; i < wordListSize; i++) words[n++] = wordList[i];
  int foundEnd = 0;
  for (int i = 0; i < n; i++) {
    if (strcmp(words[i], endWord) == 0) foundEnd = 1;
  }
  *returnSize = 0;
  if (!foundEnd) return NULL;
  char **res = (char **)malloc(sizeof(char *) * (n + 1));
  int *prev = (int *)malloc(sizeof(int) * n);
  int *dist = (int *)malloc(sizeof(int) * n);
  for (int i = 0; i < n; i++) {
    prev[i] = -1;
    dist[i] = -1;
  }
  int *queue = (int *)malloc(sizeof(int) * n);
  int head = 0, tail = 0;
  queue[tail++] = 0;
  dist[0] = 0;
  int endIdx = -1;
  while (head < tail) {
    int u = queue[head++];
    if (strcmp(words[u], endWord) == 0) {
      endIdx = u;
      break;
    }
    for (int v = 0; v < n; v++) {
      if (dist[v] == -1 && diffOne(words[u], words[v]) == 1) {
        dist[v] = dist[u] + 1;
        prev[v] = u;
        queue[tail++] = v;
      }
    }
  }
  if (endIdx == -1) return NULL;
  int len = 0;
  int cur = endIdx;
  while (cur != -1) {
    res[len++] = words[cur];
    cur = prev[cur];
  }
  for (int i = 0; i < len / 2; i++) {
    char *t = res[i];
    res[i] = res[len - 1 - i];
    res[len - 1 - i] = t;
  }
  *returnSize = len;
  free(prev);
  free(dist);
  free(queue);
  free(words);
  return res;
}

class Solution {
  bool diffOne(const string &a, const string &b) {
    int diff = 0;
    for (size_t i = 0; i < a.size(); i++) {
      if (a[i] != b[i]) diff++;
    }
    return diff == 1;
  }

public:
  vector<string> findLadders(string beginWord, string endWord, vector<string> &wordList) {
    vector<string> words = {beginWord};
    for (const string &w : wordList) words.push_back(w);
    int n = words.size();
    int endIdx = -1, beginIdx = 0;
    for (int i = 0; i < n; i++) {
      if (words[i] == endWord) endIdx = i;
    }
    if (endIdx == -1) return {};

    vector<int> dist(n, -1), prev(n, -1);
    vector<int> queue = {beginIdx};
    dist[beginIdx] = 0;
    int head = 0, found = -1;
    while (head < (int)queue.size()) {
      int u = queue[head++];
      if (u == endIdx) {
        found = u;
        break;
      }
      for (int v = 0; v < n; v++) {
        if (dist[v] == -1 && diffOne(words[u], words[v])) {
          dist[v] = dist[u] + 1;
          prev[v] = u;
          queue.push_back(v);
        }
      }
    }
    if (found == -1) return {};
    vector<string> res;
    for (int cur = found; cur != -1; cur = prev[cur]) res.push_back(words[cur]);
    reverse(res.begin(), res.end());
    return res;
  }
};

func diffOne(a, b string) bool {
	diff := 0
	for i := 0; i < len(a); i++ {
		if a[i] != b[i] {
			diff++
		}
	}
	return diff == 1
}

func findLadders(beginWord string, endWord string, wordList []string) []string {
	words := append([]string{beginWord}, wordList...)
	n := len(words)
	endIdx := -1
	for i := 0; i < n; i++ {
		if words[i] == endWord {
			endIdx = i
		}
	}
	if endIdx == -1 {
		return []string{}
	}
	dist := make([]int, n)
	prev := make([]int, n)
	for i := range dist {
		dist[i] = -1
		prev[i] = -1
	}
	queue := []int{0}
	dist[0] = 0
	found := -1
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		if u == endIdx {
			found = u
			break
		}
		for v := 0; v < n; v++ {
			if dist[v] == -1 && diffOne(words[u], words[v]) {
				dist[v] = dist[u] + 1
				prev[v] = u
				queue = append(queue, v)
			}
		}
	}
	if found == -1 {
		return []string{}
	}
	res := []string{}
	for cur := found; cur != -1; cur = prev[cur] {
		res = append(res, words[cur])
	}
	for i, j := 0, len(res)-1; i < j; i, j = i+1, j-1 {
		res[i], res[j] = res[j], res[i]
	}
	return res
}

class Solution {
  private boolean diffOne(String a, String b) {
    int diff = 0;
    for (int i = 0; i < a.length(); i++) {
      if (a.charAt(i) != b.charAt(i)) diff++;
    }
    return diff == 1;
  }

  public List<String> findLadders(String beginWord, String endWord, List<String> wordList) {
    List<String> words = new ArrayList<>();
    words.add(beginWord);
    words.addAll(wordList);
    int n = words.size();
    int endIdx = -1;
    for (int i = 0; i < n; i++) if (words.get(i).equals(endWord)) endIdx = i;
    if (endIdx == -1) return new ArrayList<>();

    int[] dist = new int[n];
    int[] prev = new int[n];
    for (int i = 0; i < n; i++) {
      dist[i] = -1;
      prev[i] = -1;
    }
    Queue<Integer> queue = new ArrayDeque<>();
    queue.add(0);
    dist[0] = 0;
    int found = -1;
    while (!queue.isEmpty()) {
      int u = queue.poll();
      if (u == endIdx) {
        found = u;
        break;
      }
      for (int v = 0; v < n; v++) {
        if (dist[v] == -1 && diffOne(words.get(u), words.get(v))) {
          dist[v] = dist[u] + 1;
          prev[v] = u;
          queue.add(v);
        }
      }
    }
    if (found == -1) return new ArrayList<>();
    List<String> res = new ArrayList<>();
    for (int cur = found; cur != -1; cur = prev[cur]) res.add(words.get(cur));
    Collections.reverse(res);
    return res;
  }
}

impl Solution {
  pub fn find_ladders(begin_word: String, end_word: String, word_list: Vec<String>) -> Vec<String> {
    let mut words = vec![begin_word];
    words.extend(word_list);
    let n = words.len();
    let end_idx = match words.iter().position(|w| *w == end_word) {
      Some(i) => i,
      None => return vec![],
    };
    let diff_one = |a: &str, b: &str| -> bool {
      a.bytes().zip(b.bytes()).filter(|(x, y)| x != y).count() == 1
    };
    let mut dist = vec![-1i32; n];
    let mut prev = vec![-1i32; n];
    let mut queue = vec![0usize];
    dist[0] = 0;
    let mut found = -1i32;
    let mut head = 0;
    while head < queue.len() {
      let u = queue[head];
      head += 1;
      if u == end_idx {
        found = u as i32;
        break;
      }
      for v in 0..n {
        if dist[v] == -1 && diff_one(&words[u], &words[v]) {
          dist[v] = dist[u] + 1;
          prev[v] = u as i32;
          queue.push(v);
        }
      }
    }
    if found == -1 {
      return vec![];
    }
    let mut res = vec![];
    let mut cur = found;
    while cur != -1 {
      res.push(words[cur as usize].clone());
      cur = prev[cur as usize];
    }
    res.reverse();
    res
  }
}

const findLadders = (beginWord: string, endWord: string, wordList: string[]): string[] => {
  const words = [beginWord, ...wordList];
  const n = words.length;
  const endIdx = words.indexOf(endWord);
  if (endIdx === -1) return [];
  const diffOne = (a: string, b: string): boolean => {
    let diff = 0;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) diff++;
    return diff === 1;
  };
  const dist: number[] = new Array(n).fill(-1);
  const prev: number[] = new Array(n).fill(-1);
  const queue: number[] = [0];
  dist[0] = 0;
  let found = -1;
  for (let head = 0; head < queue.length; head++) {
    const u = queue[head];
    if (u === endIdx) {
      found = u;
      break;
    }
    for (let v = 0; v < n; v++) {
      if (dist[v] === -1 && diffOne(words[u], words[v])) {
        dist[v] = dist[u] + 1;
        prev[v] = u;
        queue.push(v);
      }
    }
  }
  if (found === -1) return [];
  const res: string[] = [];
  for (let cur = found; cur !== -1; cur = prev[cur]) res.push(words[cur]);
  res.reverse();
  return res;
};
